		public void SecurityZone_NoZone ()
		{
			ZoneIdentityPermission zip = BasicTestZone (SecurityZone.NoZone, false);
			Assert.IsNull (zip.ToXml ().Attribute ("Zone"), "Zone Attribute");
			Assert.IsTrue (zip.IsSubsetOf (null), "IsSubset-Null");
